FOOTER=f'''<footer class="site-footer"><p><a href="{SITE}/help/">Help</a><a href="{SITE}/centers/">Oncology Centers</a><a href="{SITE}/cancer-types/">Cancer Types</a></p><p>Vet Trial Finder is free to use. Final eligibility and enrollment decisions are made by each research or treatment team.</p></footer>'''
def wrap_html(text:str)->str:
 text=re.sub(r'<header>.*?</header>',NAV,text,count=1,flags=re.S)
 if NAV not in text:text=text.replace('<main>',NAV+'<main>',1)
 text=text.replace('</style>',SHELL_CSS+DESKTOP_CSS+'</style>',1);text=re.sub(r'<footer>.*?</footer>',FOOTER,text,count=1,flags=re.S)
 if FOOTER not in text:text.replace('</main>','</main>'+FOOTER,1)
 return text
def filter_script(selector):return f'''<script>function filterCatalog(q){{q=q.toLowerCase().trim();document.querySelectorAll('{selector}').forEach(function(x){{x.style.display=!q||x.textContent.toLowerCase().includes(q)?'':'none';}});}}</script>'''
def cancer_index(root):
 items=[]
 for key in sorted(g.DISEASE_INFO):
  label=g.display_name(key);slug=g.slugify(key);items.append(f'<div class="catalog-card"><strong>{g.esc(label)}</strong><div class="catalog-links"><a href="{SITE}/north-america/dogs/{slug}/">Dogs</a><a href="{SITE}/north-america/cats/{slug}/">Cats</a></div></div>')
 body=f'''<h1>Cancer Types</h1><p class="lead catalog-intro"><strong>Start with your pet’s diagnosis.</strong> Choose a cancer type below to see a plain-language overview, standard treatment options and current clinical trials for dogs or cats. If you are not sure of the exact diagnosis, use the Clinical Trial Finder and enter what you know.</p><input class="catalog-search" type="search" placeholder="Search cancer type" aria-label="Search cancer types" oninput="filterCatalog(this.value)"><div class="catalog-grid">{''.join(items)}</div>{filter_script('.catalog-card')}''';d=root/'cancer-types';d.mkdir(parents=True,exist_ok=True);(d/'index.html').write_text(g.page('Cancer Types | Vet Trial Finder','Browse dog and cat cancer types with current treatment studies and clinical trial listings.',body,f'{SITE}/cancer-types/'),encoding='utf-8')
def other_treatments(root):
 body=f'''<h1>Other Cancer Treatment Options</h1><p class="lead catalog-intro"><strong>Some cancer treatments are difficult to find even when they are already being used in veterinary oncology.</strong> This section collects selected options beyond routine surgery, chemotherapy and radiation, including treatments available only at certain hospitals or through special programs.</p><div class="site-grid"><a class="site-card" href="{FINDER}"><h3>Electrochemotherapy</h3><p>Find centers that offer ECT and check whether it may be worth asking about for a local tumor.</p></a><a class="site-card" href="{FINDER}"><h3>Advanced Treatments</h3><p>Selected newer or less widely available oncology treatments.</p></a><a class="site-card" href="{FINDER}"><h3>Expanded Access</h3><p>Programs that may provide access to treatment outside a standard clinical trial.</p></a></div><p>These options are not appropriate for every cancer or every pet. Use the listings to find a center or program, then confirm details with the treating team.</p>''';d=root/'other-treatments';d.mkdir(parents=True,exist_ok=True);(d/'index.html').write_text(g.page('Other Veterinary Cancer Treatments | Vet Trial Finder','Electrochemotherapy, advanced treatment options and expanded access programs for dogs and cats with cancer.',body,f'{SITE}/other-treatments/'),encoding='utf-8')
def homepage(root):
 body=f'''<section class="home-hero"><figure class="hero-photo"><img src="{SITE}/assets/kot-home.jpg" alt="Kot, the Vet Trial Finder family's cat" width="1445" height="1088"></figure><div class="hero-copy"><p class="eyebrow">Clinical Trials &amp; Experimental Treatments for Dogs and Cats</p><h1>Find clinical trials and cancer treatment options for your pet</h1><p class="lead">Search current studies by diagnosis, check participating hospitals, and find other oncology options in one place. The site is free to use.</p><div class="hero-actions"><a class="cta" href="{FINDER}">Find Trials</a><a class="secondary-cta" href="{SITE}/help/">How it works</a></div></div></section><h2>Start here</h2><div class="site-grid"><a class="site-card" href="{FINDER}"><h3>Find Clinical Trials</h3><p>Enter the diagnosis and what you know about your pet. See studies that are worth checking.</p></a><a class="site-card" href="{SITE}/cancer-types/"><h3>Browse Cancer Types</h3><p>See current studies and treatment information by diagnosis.</p></a><a class="site-card" href="{SITE}/centers/"><h3>Find Oncology Centers</h3><p>Universities, teaching hospitals, specialty hospitals and research centers.</p></a><a class="site-card" href="{SITE}/centers/"><h3>Not Just Universities</h3><p>Some studies and treatments are available through specialty hospitals and other research programs too.</p></a><a class="site-card" href="{SITE}/other-treatments/"><h3>Other Treatments</h3><p>ECT, advanced treatment options and expanded access programs.</p></a><a class="site-card" href="{SITE}/help/"><h3>Help</h3><p>What a match means, what records to prepare, costs, travel and who to contact.</p></a></div><h2>How the finder works</h2><div class="how"><div><strong>1. Enter the diagnosis</strong><span>Add the details you know. Leave anything unknown rather than guessing.</span></div><div><strong>2. Review possible matches</strong><span>Read the study requirements, location, contact details and official source.</span></div><div><strong>3. Confirm with the study team</strong><span>A match is not final eligibility. The research team makes that decision.</span></div></div>''';(root/'index.html').write_text(g.page('Vet Trial Finder | Cancer Clinical Trials for Dogs and Cats','Free finder for veterinary cancer clinical trials, research centers and other treatment options for dogs and cats.',body,f'{SITE}/'),encoding='utf-8')
def add_to_sitemap(root,urls):
 p=root/'sitemap.xml'
 if not p.exists():return
 text=p.read_text(encoding='utf-8')
 for url in urls:
  if url not in text:text=text.replace('</urlset>',f'<url><loc>{g.esc(url)}</loc></url>\n</urlset>')
 p.write_text(text,encoding='utf-8')
def copy_assets(root):
 source=Path(__file__).resolve().parent/'assets'/'kot-home.jpg';dest=root/'assets'
 if source.exists():dest.mkdir(parents=True,exist_ok=True);shutil.copy2(source,dest/source.name)
def apply_site_shell(root):
 copy_assets(root);homepage(root);cancer_index(root);other_treatments(root);add_to_sitemap(root,[f'{SITE}/cancer-types/',f'{SITE}/other-treatments/',f'{SITE}/help/',f'{SITE}/centers/'])
 for p in root.rglob('index.html'):p.write_text(wrap_html(p.read_text(encoding='utf-8')),encoding='utf-8')
 print('SITE_SHELL_OK',len(list(root.rglob('index.html'))))
